export const communityWords = (locale: string): CommunityWords => COMMUNITY_WORDS[locale as Locale] ?? COMMUNITY_WORDS.en;

/** Only the words a card in the browser says, so the page hands it no more than it needs. */
export function pickWords<K extends keyof CommunityWords>(w: CommunityWords, keys: readonly K[]): Pick<CommunityWords, K> {
  return Object.fromEntries(keys.map((k) => [k, w[k]])) as Pick<CommunityWords, K>;
}
export const CHALLENGE_KEYS = ["goalYou", "chFirst", "chSecond", "chBack", "chLevel", "chPick", "goalOf", "goalDone", "err", "kMile", "mFirst", "mSecond", "mBack", "mLevel"] as const;
export const YEAR_KEYS = ["yrTitle", "yrSoFar", "yrOpen", "yrRange", "yrSince", "yrSessions", "yrSatOf", "yrKinds", "yrBusiest", "yrBadges", "yrFirstOnly", "yrNext", "yrShare", "yrMy", "yrShareMsg", "prev", "nextB", "close"] as const;
/** The Mentorship programme's words (Mentorship.tsx): its own (mt*), what helps (hp*) and how a mentor knows the path
 *  (lk*), with Close, the general refusal and the country picker's Palestine. */
export const mentorWords = (w: CommunityWords) =>
  pickWords(w, (Object.keys(w) as (keyof CommunityWords)[]).filter((k) => /^(mt|hp|lk)/.test(k) || k === "close" || k === "err" || k === "palestine"));
